# -*- coding: utf-8 -*-
"""Deepen the 37 English weak-ELI5 nodes (c10_engl 12, c7_engl 12, c9_engl 13).
Replaces ONLY the '## ELI5' body, grounded in each node's own DEFINITION text.
Backs up every file to backups/eli5/<name> first. Verifies all other sections byte-identical.
"""
import os, re, shutil, sys

ROOT = r"D:\platform\deploy\content\enhanced_nodes_md"
BAK = r"D:\platform\deploy\backend\content_tools\lang_all\backups\eli5"

ELI5S = {
"c10_engl_cbse_07_007.md": "Think of Valli as a girl who plans her adventure the way a general plans a battle. She uses sharp observation to learn everything she needs, saves every coin with fierce determination, and then executes her first solo bus ride exactly as planned. Her willpower is total - and yet the adult world she collides with during the ride shows her things she is not yet ready to understand. In simple words: a small girl with a giant will, discovering that the world outside her village is bigger than her plan.",
"c10_engl_cbse_10_007.md": "Mr Herriot is the vet who sees the truth hiding under Tricki's fur: the dog is not ill, he is over-loved. His diagnosis is really a judgement on Mrs Pumphrey's indulgence, so instead of medicines he removes Tricki from the pampering, prescribes starvation and exercise, and lets the dog's own nature do the healing. He stays kind but firm, refusing every cream cake and brandy sent to 'build up' the patient. In simple words: a doctor wise enough to cure the owner's mistake rather than the dog's disease.",
"c10_engl_cbse_10_008.md": "The comedy of this story comes from one big misunderstanding. Mrs Pumphrey believes Tricki is gravely ill, so she treats his hospital stay like a luxury spa - sending eggs, wine and brandy to 'build him up' - while the actual treatment is simply making him eat less and run more. We readers can see the gap between what she imagines and what is really happening, and that gap is the irony. Every anxious gift she sends makes the joke funnier, because her pampering was the disease all along.",
"c10_engl_cbse_11_002.md": "Anil is the easy-going writer whose kindness works in a strange way: he hires a thief, pays him sloppily, feeds him, teaches him, and never locks his money away. That casual trust is the most generous thing about him - and it is exactly what turns Hari's theft into something worse than stealing notes. When Hari robs him, he betrays not just cash but the goodness of the one person who treated him as worth teaching. In simple words: Anil's trust is the story's silent teacher.",
"c10_engl_cbse_11_007.md": "Internal conflict is the war a character fights inside his own head, and Hari Singh fights it in full view of the reader. His trained 'thief hand' pulls out the stolen notes automatically - habit moving on its own - while a newly woken conscience reminds him of the trust he is destroying. The stolen money in his hand weighs less than the trust he is about to lose, and the whole story lives in that weighing. In simple words: the real battle is not the theft but the choice that follows it.",
"c10_engl_cbse_12_007.md": "This story is a contest between a pistol and a brain. Max has the gun but also armed gullibility - he believes whatever he is told. Ausable has no weapon at all, only unarmed intelligence: he invents a fictional balcony, and Max, trusting the story, defeats himself. Wit wins where menace fails. In simple words: the man who stays calm with a gun pointed at him is more dangerous than the man holding it.",
"c10_engl_cbse_13_007.md": "Horace Danby lives two lives: a respectable locksmith for most of the year, and a safe-breaker once a year, robbing only to fund his love of rare books. His careful methodology - the planning, the precision, the craftsman's pride in a clean job - makes him admirable and doomed at the same time. The dual life that makes him fascinating is exactly what makes him easy prey for a thief cleverer than himself. In simple words: pride in his own careful method becomes the very door his enemy walks through.",
"c10_engl_cbse_14_008.md": "Griffin proves that a brilliant brain without empathy is dangerous. He discovers the secret of invisibility - a scientific marvel - and immediately turns it into a licence for lawlessness: arson, theft, assault. Every crime is easier for a man no one can see, so his marvel becomes a menace. In simple words: genius can answer 'can I do this?', but only character can answer 'should I?' - and Griffin never asks the second question.",
"c10_engl_cbse_15_008.md": "Richard Ebright's story says a scientist is made by obsession first and intelligence second. As a boy he collected butterflies with insatiable curiosity; when collecting alone was not enough, his competitive drive pushed him to ask bigger questions, and the hobby grew step by step into prize-winning research on cell theory. Each question led to a project, each project to a discovery. In simple words: he never stopped asking 'why', and that habit - not just brains - is what made him a scientist.",
"c10_engl_cbse_16_001.md": "Matilda Loisel is a pretty woman born into a clerk's family who spends her days dreaming of luxury she cannot have. Even before any invitation arrives, she is already dissatisfied - restless, longing for silk and splendour - and that restless longing is the trap the whole story springs from. Because she feels born for a finer life, she reaches for a grandeur she cannot afford, and the borrowed shine of a single evening begins her real story. In simple words: wanting what you cannot have is this character's undoing.",
"c10_engl_cbse_17_008.md": "Bholi's teacher is the first person who looks past a stammering, pock-marked girl and sees the person inside. Where the world offers ridicule, she offers empathy and patience - she speaks softly, waits quietly, and gives a frightened child the encouragement nobody else would. That quiet vision works year after year until the 'dumb cow' can stand before the whole village and refuse an unjust marriage with a steady voice. In simple words: one teacher's kindness turned a silenced child into a woman with courage.",
"c10_engl_cbse_18_009.md": "The comedy here works by complete reversal: a Martian invasion fleet is defeated not by weapons but by a nursery-rhyme book the invaders mistake for a secret code. We readers know it is just a book of rhymes, but the Martians take everything literally - and their literal-mindedness turns pulp science fiction into a joke. The mightiest invasion in the universe retreats from something harmless. In simple words: the thing that 'saves the Earth' is nothing but a children's rhyme book, and that is exactly the irony.",
"c7_engl_ch01_002.md": "Jahnavi is a village girl with one fierce dream: to read and write. Everyone around her accepts that a girl like her cannot have school, but she longs for it anyway - and one day the river itself seems to speak to her, strengthening her resolve. Her character is built from watching, wanting and refusing to let the dream die, even with every barrier standing around her. In simple words: a girl whose determination is stronger than the rules trying to keep her uneducated.",
"c7_engl_ch01_010.md": "The central message of this story is simple and strong: education is worth fighting for. The author builds the idea step by step - first the barrier (a girl told that school is not for her), then the silent struggle, then the breakthrough when she finds a way to make her voice heard. The deeper point is that social barriers denying girls schooling are made by people, and what people build, people can challenge and overcome. In simple words: never accept 'girls cannot learn' - question it until it falls.",
"c7_engl_ch02_001.md": "Dr Dolittle is a doctor defined by one thing: extraordinary empathy for animals. He gives up his human patients and starts learning animal languages so he can understand and care for creatures properly - and he does it driven by genuine love, not profit. His choices look foolish to the practical world, but his heart is simply larger than most. In simple words: a man so kind that he learned to talk with animals just to understand where it hurts.",
"c7_engl_ch02_007.md": "Words like 'scholar', 'vet', 'cracker' and 'sense' can puzzle you until you let the sentence decide their meaning. That is contextual word analysis: instead of running to a dictionary, you read how the word is used around it. A 'vet' in this story is an animal doctor; a word that normally suggests fireworks or biscuits can mean something entirely different here. In simple words: the sentence is the dictionary - read the neighbours of a word and it explains itself.",
"c7_engl_ch02_010.md": "This story tries to build empathy for animals, and your job is to judge how well it succeeds - not just repeat the theme. When Dolittle can hear what animals actually want instead of humans guessing, we readers start feeling the animal's side of every human-animal relationship too. Test it on yourself: after reading, do you see a stray animal differently? In simple words: the story's claim is 'animals have feelings too', and evaluation means deciding whether the story truly proves it.",
"c7_engl_ch03_001.md": "Anand is the enthusiastic inventor whose gadgets keep failing spectacularly. He is driven, overconfident, always mid-project - and a comic disaster for his long-suffering family. But read his traits closely: the same qualities behind the chaos are the ones real inventors are made of, and the story knows it. In simple words: today he is the family's favourite disaster, and tomorrow that same stubborn confidence might build something that actually works.",
"c7_engl_ch03_002.md": "The narrator of this story is Anita, Anand's sister, and her point of view shapes everything we see. She describes her brother's chaos with affectionate exasperation - annoyed by the noise and the failed inventions, yet fond of the dreamer causing them. Because the events come through her eyes, Anand reads as lovable rather than foolish, and the parents' exasperation reads as warm rather than angry. In simple words: the same story told by a different narrator would not be funny at all - the narrator's love is the comedy.",
"c7_engl_ch03_010.md": "The question this node makes you judge: does Anand's journey actually teach perseverance and creative problem-solving, or does it just celebrate failure with humour? Look at the evidence - his inventions collapse again and again, and he returns to the workbench every time. The story never mocks him for trying; the comedy wraps a serious lesson. In simple words: trying again after every crash is how problem-solving is really learned, and the humour is only the wrapping paper.",
"c7_engl_ch04_002.md": "Suraj starts as a watcher and becomes an adventurer. Curious and restless, he stands near the railway line watching trains burst through the jungle tunnel in wonder, always wondering what is inside that darkness. Then one day he stops only watching - he acts on the urge and goes to explore the tunnel himself. That shift from passive watcher to active adventurer is his whole character. In simple words: a boy whose curiosity finally grew brave enough to act.",
"c7_engl_ch04_007.md": "This chapter teaches you words the way stories teach them best: inside the sentences that carry them. Instead of memorising dictionary entries, you watch how 'The Tunnel' uses each of four words in its own vivid descriptions - and the meaning becomes clear from the picture the sentence paints. Then you practise using the same words in your own prose. In simple words: meet new words inside a story and they stick far better than any word-list.",
"c7_engl_ch04_010.md": "In this story, courage and curiosity are two different pulls on the same boy. Curiosity is what draws Suraj toward the dark tunnel - the urge to know what is inside. Courage is what lets him see the risk clearly and go in anyway. Take either one away and the adventure dies: without curiosity he would never wonder; without courage he would never enter. In simple words: being brave does not mean feeling no fear - it means wanting the answer more than the safety.",
"c7_engl_ch05_010.md": "This chapter makes a big claim: that the freedom and peace civilians take for granted were bought by soldiers' sacrifices. Your job is to critically evaluate how strongly it argues that case. The evidence it sets before you: soldiers guarding freezing borders at night while others sleep peacefully, the parades we watch without seeing the cost behind them. Ask yourself whether the writing makes you feel the price, or merely states it. In simple words: the theme is 'freedom is never free', and evaluation means testing whether the chapter earns that claim.",
"c9_engl_ch1_2.md": "Krishtakka, the grandmother, begins the story as a dependent listener - she needs her granddaughter to read the serial to her - and ends it as an independent reader, finishing the novel with her own eyes. Her vulnerability about her illiteracy, her deep cultural rootedness, and her iron determination to learn at her age make her the emotional core of the story. She turns shame into effort and effort into freedom. In simple words: a grandmother who proves it is never too late to learn.",
"c9_engl_ch1_8.md": "The key words of this chapter are not decoration - each one is a rung in the grandmother's climb. 'Illiterate' and 'dependence' describe where she starts; 'determined' describes the effort; 'empowerment', 'independence' and 'transformation' describe where she lands. Learn these words and you hold the story's whole arc - from helplessness to self-reliance - in a single list. In simple words: the vocabulary of this chapter is the journey itself, wearing seven different masks.",
"c9_engl_ch2_2.md": "Sentila wants to make pots in a world that keeps telling her pot-making is not her place. Her rebellion is quiet: no shouting, only determination, patience and deep respect for the craft - learning the wheel properly and refusing to abandon it. Her persistence is the engine of the whole story, pushing against her family's plans step by step. In simple words: she wins not by fighting loudly but by simply becoming too good at what she loves to be stopped.",
"c9_engl_ch2_3.md": "Arenla is the supporting figure whose own traits - caution, loyalty, scepticism - throw Sentila's determination into sharp relief. She sees the craft her daughter loves as a low-status path and security lying elsewhere, so her opposition comes from protectiveness, not cruelty. Reading her character answers the story's deeper question: who gets to shape a life - the one living it or the ones guiding it? In simple words: Arenla is the wall of doubt that makes Sentila's persistence mean something.",
"c9_engl_ch3_8.md": "A pankha stops being just 'a fan' the moment you learn its craft-words. Materials: bamboo, cane, khus, palm leaf. Techniques: plaiting, weaving, applique. Parts: handle, guard, ribs. Design terms: symmetry, motif, border. With this lexicon you could write an honest museum label for an old pankha - describing a crafted object with named parts, not just a pretty fan. In simple words: every craft has its own vocabulary, and learning it is like being handed the key to a workshop.",
"c9_engl_ch4_2.md": "Grandpa is built around one stubborn idea: his independence. He manages his own routines, refuses to be treated as fragile, and would rather struggle alone than be handled. That insistence creates the story's central tension - the family's anxious care keeps colliding with his autonomy. In simple words: an old man whose deepest fear is not illness but becoming a patient, someone whose life is run by other people.",
"c9_engl_ch4_3.md": "Ravi and Vidya guard the same grandfather from opposite sides. Ravi approaches with eager protectiveness - help, fix, watch over. Vidya responds with measured watchfulness - observe, wait, let him manage. Placed side by side, they explore the story's hard question: where does safety end and smothering begin? In simple words: one loves by doing too much, the other by holding back just enough - and the old man needs both to keep his dignity.",
"c9_engl_ch4_8.md": "The words this chapter builds around its subject - independence, dignity, routine, fragility, care, concern - are the working vocabulary of the aging-and-care argument. They appear in newspapers and policy documents too, because they carry one big idea: growing old with respect. Learn them and you can talk about care that honours the person being cared for, not care that merely manages them. In simple words: this word-list is the toolkit for the difference between looking after someone and looking down at them.",
"c9_engl_ch5_8.md": "This chapter hands you the specialised lexicon of Para sport: classification, adaptive sports, spinal cord injury, podium finish - and, with them, disability terminology used with dignity rather than pity. Meet each word inside its own world - a classifier verifying an athlete's category before a final - and the terms stop being jargon. The words themselves argue the chapter's thesis: limits are made to be broken. In simple words: the right vocabulary lets you speak of Para athletes the way this chapter does - as competitors first.",
"c9_engl_ch6_2.md": "Shruti Sharma is a young musician torn between two pulls: the inherited tradition she was trained in and the personal innovation growing inside her. Her internal conflict is the real plot of the play, and her growth arc and relationships carry its central question - does honouring the past mean repeating it, or can something new grow from old roots? In simple words: she learns that tradition is a river, not a museum piece - it can flow and still remain itself.",
"c9_engl_ch6_3.md": "Guru Nabin Sharma is the teacher-father figure whose reverence for tradition both inspires and constrains. His authority shapes every lesson; his love for his student is real; but his symbolic role as guardian of classical form leaves little space for the new sound she hears in her head. In simple words: he is not the enemy of change - he is a man who believes the past is precious, and the play asks whether his guarding protects the music or cages it.",
"c9_engl_ch7_7.md": "This chapter's thematic vocabulary maps a world most of us never enter: Gramin Dak Sewak, mail route, remote delivery, arid terrain - the word-stock of the Thar Desert and India's postal network. Read a sentence like 'the scorching wind whipped across the dunes, but the Gramin Dak Sewak kept pedaling' and the words stop being barriers; they paint the daily heroism of the postman. In simple words: these terms are the chapter's honour-list for the man who connects villages the maps forget.",
"c9_engl_ch8_8.md": "The mother's letter teaches ambition through its own word choices: conviction, perseverance, endeavour, resilience, sacrifice, steadfast, unwavering. Notice that none of these words travels alone - each arrives attached to a struggle or a sacrifice, because that is how she passes her vocabulary of ambition to her child. This is context-dependent vocabulary: the passage's argument decides what the words mean. In simple words: saying 'unwavering focus' instead of 'I tried hard' hands the listener a whole mindset in two words.",
}

def main():
    os.makedirs(BAK, exist_ok=True)
    ok, fails = [], []
    for name, new in ELI5S.items():
        p = os.path.join(ROOT, name)
        try:
            with open(p, encoding="utf-8") as f:
                old = f.read()
            m = re.search(r"(## ELI5\n)(.*?)(?=\n## )", old, re.S)
            assert m, "no ELI5 section"
            if len(new) < 150:
                raise AssertionError("new ELI5 still <150 chars")
            bp = os.path.join(BAK, name)
            if not os.path.exists(bp):
                shutil.copyfile(p, bp)
            newtext = old[:m.start(2)] + new + old[m.end(2):]
            assert "\ufffd" not in newtext, "U+FFFD introduced"
            o_sec = re.split(r"\n## ", old)
            n_sec = re.split(r"\n## ", newtext)
            assert len(o_sec) == len(n_sec), "section count changed"
            diff = [i for i, (a, b) in enumerate(zip(o_sec, n_sec)) if a != b]
            eli5_idx = [i for i, s in enumerate(o_sec)
                        if s.startswith("ELI5\n") or s.startswith("## ELI5\n")]
            assert diff == eli5_idx, f"changed non-ELI5 sections: {diff} vs {eli5_idx}"
            with open(p, "w", encoding="utf-8", newline="") as f:
                f.write(newtext)
            ok.append(name)
        except Exception as e:
            fails.append((name, repr(e)))
    print(f"patched OK: {len(ok)} / {len(ELI5S)}")
    for n, e in fails:
        print(f"  FAIL {n}: {e}")
    # spot re-verify from disk
    short = []
    for name in ELI5S:
        with open(os.path.join(ROOT, name), encoding="utf-8") as f:
            t = f.read()
        m = re.search(r"## ELI5\n(.*?)(?=\n## )", t, re.S)
        if not m or len(m.group(1)) < 150:
            short.append(name)
    print(f"re-verified short-from-disk: {len(short)} {short[:5]}")
    return 0 if not fails and not short else 1

if __name__ == "__main__":
    sys.exit(main())
